  }
  .poster {
    width: 505px;
    height: 750px;
    background: #f2c9d3;
    padding: 12px;
    box-sizing: border-box;
    position: relative;
  }
  .inner {
    width: 100%;
    height: 100%;
    background: #ffffff;
    position: relative;
    overflow: hidden;
  }

  .prime-video {
    text-align: center;
    padding-top: 22px;
  }
  .prime-video .brand {
    font-size: 26px;
    font-weight: bold;
    letter-spacing: 0.5px;
    color: #000;
  }
  .prime-video .smile {
    display: block;
    margin: 0 auto;
    width: 90px;
    height: 10px;
    border-bottom: 5px solid #ff9900;
    border-radius: 0 0 50% 50%;
    margin-top: 2px;
  }

  .director-line {
    text-align: center;
    margin-top: 18px;
    font-size: 11px;
    letter-spacing: 1px;
    color: #1a1a4d;
  }
  .director-name {
    text-align: center;
    font-weight: bold;
    font-size: 13px;
    letter-spacing: 1px;
    color: #1a1a4d;
    margin-top: 2px;
  }

  .tagline {
    text-align: center;
    font-family: 'Brush Script MT', cursive;
    color: #c2185b;
    font-size: 20px;
    line-height: 1.1;
    margin-top: 14px;
  }

  .photo-area {
    position: relative;
    width: 100%;
    height: 350px;
    margin-top: 6px;
  }
  .placeholder {
    position: absolute;
    background: repeating-linear-gradient(45deg, #eee, #eee 10px, #ddd 10px, #ddd 20px);
    border: 1px dashed #999;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    font-size: 11px;
    color: #555;
    box-sizing: border-box;
    padding: 4px;
  }
  .ph-woman {
    left: 15px;
    top: 0px;
    width: 230px;
    height: 350px;
  }
  .ph-man {
    left: 260px;
    top: 30px;
    width: 220px;
    height: 320px;
  }

  .title-block {
    text-align: center;
    margin-top: 4px;
  }
  .title-block .title {
    font-family: 'Brush Script MT', cursive;
    font-size: 44px;
    color: #1a1a5e;
    line-height: 1;
  }
  .title-block .title .possible {
    color: #c2185b;
    font-weight: bold;
  }

  .credits-line {
    text-align: center;
    font-size: 8px;
    letter-spacing: 0.5px;
