    margin-top: 8px;
  }
  .credits-line .label {
    color: #666;
  }
  .credits-line .name {
    font-weight: bold;
  }

  .bottom-logos {
    position: absolute;
    bottom: 40px;
    left: 0;
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 15px;
    box-sizing: border-box;
  }
  .bottom-logos .logo-ph {
    width: 55px;
    height: 22px;
    font-size: 6px;
    background: #f5f5f5;
    border: 1px solid #ccc;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: #777;
  }

  .release-line {
    position: absolute;
    bottom: 10px;
    left: 0;
    width: 100%;
    text-align: center;
    font-size: 15px;
    font-weight: bold;
    letter-spacing: 1px;
    color: #111;
  }
  .release-line .sep {
    margin: 0 8px;
    color: #999;
    font-weight: normal;
  }
</style>
